-- ============================================================
-- KaaryaSetu / Dayflow HRMS — Complete Enterprise Data Seed (200 Employees)
-- File: data.sql
-- Covers: Employees, Users, Attendance, Regularizations, Leaves,
--         Salary Structures, Payroll (July/Aug), Holidays,
--         Announcements, Recruitment Applications, Feedback, Audit Logs
-- ============================================================

-- Ensure required unique constraints exist for ON CONFLICT clauses
DO $$ BEGIN
  ALTER TABLE users ADD CONSTRAINT unique_users_email UNIQUE(email);
EXCEPTION WHEN OTHERS THEN NULL; END $$;

DO $$ BEGIN
  ALTER TABLE salary_structures ADD CONSTRAINT unique_salary_emp UNIQUE(employee_id);
EXCEPTION WHEN OTHERS THEN NULL; END $$;

DO $$ BEGIN
  ALTER TABLE leave_balances ADD CONSTRAINT unique_emp_leave_type_year UNIQUE(employee_id, leave_type, year);
EXCEPTION WHEN OTHERS THEN NULL; END $$;

DO $$ BEGIN
  ALTER TABLE attendance ADD CONSTRAINT unique_employee_date UNIQUE(employee_id, date);
EXCEPTION WHEN OTHERS THEN NULL; END $$;

DO $$ BEGIN
  ALTER TABLE payroll ADD CONSTRAINT unique_payroll_emp_period UNIQUE(employee_id, month, year);
EXCEPTION WHEN OTHERS THEN NULL; END $$;

DO $$ BEGIN
  ALTER TABLE holidays ADD CONSTRAINT unique_holidays_date UNIQUE(date);
EXCEPTION WHEN OTHERS THEN NULL; END $$;

-- Clean existing records safely
TRUNCATE TABLE audit_logs, notifications, announcements, holidays, payroll,
  salary_structures, leaves, leave_balances, attendance_regularization,
  attendance, recruitment_applications, anonymous_feedback, users, employees, designations, departments CASCADE;

-- 1. DEPARTMENTS
ON CONFLICT (code) DO NOTHING;

-- 2. DESIGNATIONS
ON CONFLICT (id) DO NOTHING;

-- 3. EMPLOYEES (200 records)

-- 4. USER ACCOUNTS (Password: Dayflow@2026)
ON CONFLICT (email) DO NOTHING;

-- 5. SALARY STRUCTURES
ON CONFLICT (employee_id) DO NOTHING;

-- 6. LEAVE BALANCES (2026)
ON CONFLICT (employee_id, leave_type, year) DO NOTHING;

-- 7. ATTENDANCE LOGS (Past 7 Days)
ON CONFLICT (employee_id, date) DO NOTHING;

-- 8. LEAVE REQUESTS

-- 9. PAYROLL (July & August 2026)
ALTER TABLE payroll ADD COLUMN IF NOT EXISTS payment_date DATE;
ON CONFLICT (employee_id, month, year) DO NOTHING;

-- 10. HOLIDAYS (2026 Calendar)
ON CONFLICT (date) DO NOTHING;

-- 11. ANNOUNCEMENTS

-- 12. RECRUITMENT APPLICATIONS

-- 13. ANONYMOUS FEEDBACK

-- 14. AUDIT LOGS
